INSERT INTO meta_catalogo_tablas VALUES ('gaia_source', 'Catálogo principal', 'gaiadr3', 'gaia_source', 'TAP Gaia (ADQL)', 'This table has an entry for every Gaia observed source as published with this data release. It contains the basic source parameters, in their final state as processed by the Gaia Data Processing and Analysis Consortium from the raw data coming from the spacecraft. The table is complemented with others containing information specific to certain kinds of objects (e.g.~Solar--system objects, non--single stars, variables etc.) and value--added processing (e.g.~astrophysical parameters etc.). Further array data types (spectra, epoch measurements) are presented separately via Datalink resources.', 152, 1811709771, 753.026, 'https://cdn.gea.esac.esa.int/?prefix=Gaia/gdr3/gaia_source/');
INSERT INTO meta_catalogo_tablas VALUES ('gaia_source', 'Catálogo principal', 'gaiadr3', 'gaia_source_lite', 'TAP Gaia (ADQL)', 'This is a column-wise subset of the gaia_source table named gaia_source_lite. This table has an entry for every Gaia observed source as published with this data release. It contains the basic source parameters, in their final state as processed by the Gaia Data Processing and Analysis Consortium from the raw data coming from the spacecraft. The table is complemented with others containing information specific to certain kinds of objects (e.g.~Solar--system objects, non--single stars, variables etc.) and value--added processing (e.g.~astrophysical parameters etc.). Further array data types (spectra, epoch measurements) are presented separately via Datalink resources.', 51, 1811709771, NULL, '(solo en el Archivo Gaia; bulk en https://cdn.gea.esac.esa.int/?prefix=Gaia/gedr3/)');
INSERT INTO meta_catalogo_tablas VALUES ('Astrophysical_parameters', 'Parámetros astrofísicos', 'gaiadr3', 'astrophysical_parameters', 'TAP Gaia (ADQL)', 'This is the main table containing the 1D astrophysical parameters produced by the Apsis processing chain developed in Gaia DPAC CU8 (see Chapter~\ref{chap:cu8par}). Additional parameters can be found in table {\tt AstrophysicalParametersSupp}.', 226, 1590932717, 255.974, 'https://cdn.gea.esac.esa.int/?prefix=Gaia/gdr3/Astrophysical_parameters/astrophysical_parameters/');
INSERT INTO meta_catalogo_tablas VALUES ('Astrophysical_parameters', 'Parámetros astrofísicos', 'gaiadr3', 'astrophysical_parameters_supp', 'TAP Gaia (ADQL)', 'This table contains additional parameters from the Apsis processing chain, compared to the main table {\tt AstrophysicalParameters} (see Chapter~\ref{chap:cu8par}), from modules that produce more than one result for a parameter. It contains (1) the individual library results from GSP-Phot (see Section~\ref{ssec:cu8par_apsis_gspphot_method}), (2) FLAME results from processing GSP-Spec parameters given in the {\tt AstrophysicalParameters} table (see Section~\ref{ssec:cu8par_apsis_flame}), and (3) results from the GSP-Spec ANN algorithm (see Section~\ref{ssec:cu8par_apsis_gspspec}).', 175, 473020612, 200.948, 'https://cdn.gea.esac.esa.int/?prefix=Gaia/gdr3/Astrophysical_parameters/astrophysical_parameters_supp/');
INSERT INTO meta_catalogo_tablas VALUES ('Astrophysical_parameters', 'Parámetros astrofísicos', 'gaiadr3', 'mcmc_samples_gsp_phot', 'DataLink (MCMC_GSPPHOT)', 'This is the DataLink table hosting Monte-Carlo Markov Chain (MCMC) samples for the posterior probability distribution of all parameters derived from the General Stellar Parametrizer from Photometry (GSP-Phot, see Section~\ref{ssec:cu8par_apsis_gspphot} in the online documentation). 2000 MCMC samples are provided for 1) all sources brighter than G=12, 2) a random subset of 0.1\% of the sources fainter than G=12. For all other sources fainter than G=12, the sample size is 100 (the last 100 samples in the MCMC). The table considers the following parameters: \begin{itemize} \item effective temperature $T_{\rm eff}$ in K \item monochromatic extinction at 547.7~nm $A_0$ in mag \item surface gravity $\log g$ \item metallicity [M/H] \item $G$-band extinction in mag \item absolute magnitude $M_{\rm G}$ in mag \item distance in pc \item $G_{\rm BP}$ band extinction $A_{\rm BP}$ in mag \item $G_{\rm RP}$ band extinction $A_{\rm RP}$ in mag \item reddening $E(G_{\rm BP} - G_{\rm RP}) = A_{\rm BP} - A_{\rm RP}$ in mag \item logarithmic posterior probability \item logarithmic likelihood \item stellar radius in $R_\odot$ \end{itemize} Note this table is not available through the main archive TAP interface. Data are delivered via the Massive Data service indexed by the VO Datalink protocol and described in Chapter~\ref{chap:archive}. For example this can be actioned in the archive user interface by querying the main source catalogue {\tt GaiaSource} and selecting {\tt hasMcmcGspphot}~{\tt = ''t''}.', 16, NULL, 3263.258, 'https://cdn.gea.esac.esa.int/?prefix=Gaia/gdr3/Astrophysical_parameters/mcmc_samples_gsp_phot/');
INSERT INTO meta_catalogo_tablas VALUES ('Astrophysical_parameters', 'Parámetros astrofísicos', 'gaiadr3', 'mcmc_samples_msc', 'DataLink (MCMC_MSC)', 'This is the DataLink table hosting Monte-Carlo Markov Chain (MCMC) samples for the posterior probability distribution of all parameters derived from the Multiple Source Classifier (MSC, see Section~\ref{ssec:cu8par_apsis_msc} in the online documentation). 100 random MCMC samples are provided for each source. The table considers the following parameters: \begin{itemize} \item effective temperature $T_{\rm eff, 1}$ of the primary star \item effective temperature $T_{\rm eff, 2}$ of the secondary star \item surface gravity $\log g_1$ of the primary star \item surface gravity $\log g_2$ of the secondary star \item monochromatic extinction at 547.7~nm $A_0$ \item metallicity [M/H] \item distance \item logarithmic posterior probability \item logarithmic likelihood \end{itemize} Note this table is not available through the main archive TAP interface. Data are delivered via the Massive Data service indexed by the VO Datalink protocol and described in Chapter~\ref{chap:archive}. For example this can be actioned in the archive user interface by querying the main source catalogue {\tt GaiaSource} and selecting {\tt hasMcmcMsc}~{\tt = ''t''}.', 12, NULL, 1393.553, 'https://cdn.gea.esac.esa.int/?prefix=Gaia/gdr3/Astrophysical_parameters/mcmc_samples_msc/');
INSERT INTO meta_catalogo_tablas VALUES ('Astrophysical_parameters', 'Parámetros astrofísicos', 'gaiadr3', 'oa_neuron_information', 'TAP Gaia (ADQL)', 'This is the table hosting the content of a Self-Organized Map calculated from a dataset composed by outliers by the Apsis module OA. Each entry corresponds to parameters estimated for one particular neuron of the map. The prototype BP/RP spectrum for a particular neuron is available in another table: {\tt OaNeuronXpSpectra}. See Section~\ref{ssec:cu8par_apsis_oa} for further details.', 78, 900, 0.0, 'https://cdn.gea.esac.esa.int/?prefix=Gaia/gdr3/Astrophysical_parameters/oa_neuron_information/');
INSERT INTO meta_catalogo_tablas VALUES ('Astrophysical_parameters', 'Parámetros astrofísicos', 'gaiadr3', 'oa_neuron_xp_spectra', 'TAP Gaia (ADQL)', 'This is the table hosting the prototype BP/RP spectrum corresponding to each of the neurons of the Self-Organised-Map produced by the Apsis module OA. Other neuron attributes, such as statistics on various parameters, are available in another table: {\tt OaNeuronInformation}. See Section~\ref{ssec:cu8par_apsis_oa} for further details.', 7, 78300, 0.001, 'https://cdn.gea.esac.esa.int/?prefix=Gaia/gdr3/Astrophysical_parameters/oa_neuron_xp_spectra/');
INSERT INTO meta_catalogo_tablas VALUES ('Astrophysical_parameters', 'Parámetros astrofísicos', 'gaiadr3', 'total_galactic_extinction_map', 'TAP Gaia (ADQL)', 'This table provides the Total Galactic Extinction (TGE) map for extinction parameters $A_0$ describing the effective total Galactic extinction and related uncertainties at four separate HEALPix levels, namely levels 6 to 9. For further details see Section \ref{ssec:cu8par_apsis_tge} of the online documentation.', 10, 4177920, 0.039, 'https://cdn.gea.esac.esa.int/?prefix=Gaia/gdr3/Astrophysical_parameters/total_galactic_extinction_map/');
INSERT INTO meta_catalogo_tablas VALUES ('Astrophysical_parameters', 'Parámetros astrofísicos', 'gaiadr3', 'total_galactic_extinction_map_opt', 'TAP Gaia (ADQL)', 'This table provides an optimum version of the Total Galactic Extinction map, derived from the table {{TotalGalacticExtinctionMap}} at a single HEALPix level 9. For this, the mean effective total Galactic extinction and related uncertainties have been selected from the optimal HEALPix level of the four offered in {{TotalGalacticExtinctionMap}}. For further details see Section \ref{ssec:cu8par_apsis_tge} of the online documentation.', 7, 3145728, 0.012, 'https://cdn.gea.esac.esa.int/?prefix=Gaia/gdr3/Astrophysical_parameters/total_galactic_extinction_map_opt/');
INSERT INTO meta_catalogo_tablas VALUES ('Cross-match', 'Cruce con catálogos externos', 'gaiadr3', 'allwise_best_neighbour', 'TAP Gaia (ADQL)', '<p>allWISE BestNeighbour table lists each matched Gaia object with its best neighbour in the external catalogue. The cross-match algorithm is not symmetric and searches Gaia sources counterparts in allWISE.<br/> The best neighbour is chosen among good neighbours as the one with the highest value of the figure of merit, which evaluates the ratio between two opposite models/hypotheses: the counterpart candidate is a match or it is found by chance. Good neighbours are nearby objects in the external catalogue whose position is compatible within position errors with the Gaia target.<br/> The cross-match algorithm is positional and exploits the full 5 parameters covariance matrix of Gaia astrometric solution when available and the external catalogue positions and position errors. In addition it takes into account the external catalogue environment using the local density.<br/> <br/> Please note that the cross-match algorithm is a trade-off between multiple requirements, in particular between completeness and correctness. It is thus not limited to a simple cone search.<br/> <br/> Reference papers:<br/> </p> <p>DR1-DPACP-17<br/> </p> <p>DR2-DPACP-41<br/> </p>', 7, 324115003, NULL, '(solo en el Archivo Gaia; bulk en https://cdn.gea.esac.esa.int/?prefix=Gaia/gedr3/)');
INSERT INTO meta_catalogo_tablas VALUES ('Cross-match', 'Cruce con catálogos externos', 'gaiadr3', 'allwise_neighbourhood', 'TAP Gaia (ADQL)', '<p>allWISE Neighbourhood table includes all good neighbours for each matched Gaia object. A good neighbour for a given Gaia source is a nearby object in the external catalogue whose position is compatible (within position errors) with the Gaia target. <br/> The cross-match algorithm is not symmetric and searches Gaia sources counterparts in allWISE. The cross-match algorithm is positional and exploits the full 5 parameters covariance matrix of Gaia astrometric solution when available and the external catalogue positions and position errors. In addition it takes into account the external catalogue environment using the local density.<br/> <br/> Please note that the cross-match algorithm is a trade-off between multiple requirements, in particular between completeness and correctness. It is thus not limited to a simple cone search.<br/> <br/> Reference papers:<br/> </p> <p>DR1-DPACP-17<br/> </p> <p>DR2-DPACP-41<br/> </p>', 6, 324116921, NULL, '(solo en el Archivo Gaia; bulk en https://cdn.gea.esac.esa.int/?prefix=Gaia/gedr3/)');
INSERT INTO meta_catalogo_tablas VALUES ('Cross-match', 'Cruce con catálogos externos', 'gaiadr3', 'apassdr9_best_neighbour', 'TAP Gaia (ADQL)', '<p>Table <tt>Apassdr9BestNeighbour</tt> lists each matched Gaia object with its best neighbour in the external catalogue. The cross-match algorithm is not symmetric and searches Gaia sources counterparts in APASS DR9. The best neighbour is chosen among good neighbours as the one with the highest value of the figure of merit, which evaluates the ratio between two opposite models/hypotheses: the counterpart candidate is a match or it is found by chance. Good neighbours are nearby objects in the external catalogue whose position is compatible within position errors with the Gaia target. The cross-match algorithm is positional and exploits the full&#160;5 parameter covariance matrix of Gaia astrometric solution when available and the external catalogue positions and position errors. In addition it takes into account the external catalogue environment using the local density.</p> <p>Please note that the cross-match algorithm is a trade-off between multiple requirements, in particular between completeness and correctness. It is thus not limited to a simple cone search.</p> <p>Reference papers:<br/> </p> <p>DR1-DPACP-17<br/> </p> <p>DR2-DPACP-41<br/> </p>', 7, 74904012, NULL, '(solo en el Archivo Gaia; bulk en https://cdn.gea.esac.esa.int/?prefix=Gaia/gedr3/)');
INSERT INTO meta_catalogo_tablas VALUES ('Cross-match', 'Cruce con catálogos externos', 'gaiadr3', 'apassdr9_join', 'TAP Gaia (ADQL)', 'Convenience table to be used to join the APASS DR9 catalogue with the cross-match results. The table links the external catalogue original sourceId (originalExtSourceId) to the corresponding additional numerical identifier (cleanApassdr9Oid). Both originalExtSourceId and cleanApassdr9Oid are present in the cross-match output tables (Apassdr9BestNeighbour and Apassdr9Neighbourhood). However, in case there are suspected duplicates in the external catalogue, different originalExtSourceId will correspond to the same cleanApassdr9Oid. In the cross-match output table only the originalExtSourceId of the source with the best astrometry among the suspected duplicates will be listed. In practice, users may use the originalExtSourceId in the original catalogue to find the matching source with the best astrometry. Users interested in all matching suspected duplicates should instead use the cleanApassdr9Oid in the join with the cross-match result tables. See Chapter [chap:crossmatch] for more details on the duplicates in the external catalogues and their treatment in the cross-match computations.', 2, 61176401, NULL, '(solo en el Archivo Gaia; bulk en https://cdn.gea.esac.esa.int/?prefix=Gaia/gedr3/)');
INSERT INTO meta_catalogo_tablas VALUES ('Cross-match', 'Cruce con catálogos externos', 'gaiadr3', 'apassdr9_neighbourhood', 'TAP Gaia (ADQL)', '<p>Table <tt>Apassdr9Neighbourhood</tt> includes all good neighbours for each matched Gaia object. A good neighbour for a given Gaia source is a nearby object in the external catalogue whose position is compatible (within position errors) with the Gaia target. The cross-match algorithm is not symmetric and searches Gaia sources counterparts in APASS DR9. The cross-match algorithm is positional and exploits the full&#160;5 parameter covariance matrix of the the Gaia astrometric solution when available and the external catalogue positions and position errors. In addition it takes into account the external catalogue environment using the local density.</p> <p>Please note that the cross-match algorithm is a trade-off between multiple requirements, in particular between completeness and correctness. It is thus not limited to a simple cone search.</p> <p>Reference papers:<br/> </p> <p>DR1-DPACP-17<br/> </p> <p>DR2-DPACP-41<br/> </p>', 6, 76274759, NULL, '(solo en el Archivo Gaia; bulk en https://cdn.gea.esac.esa.int/?prefix=Gaia/gedr3/)');
INSERT INTO meta_catalogo_tablas VALUES ('Cross-match', 'Cruce con catálogos externos', 'gaiadr3', 'dr2_neighbourhood', 'TAP Gaia (ADQL)', 'Users wishing to look up the E/DR3 record for an astrophysical source identified in DR2 must NOT simply extract the record from E/DR3 having the same source identifier. As described in the detailed description of attribute designation in GaiaSource it is not guaranteed that the same astronomical source will always have the same source identifier in different Data Releases. Hence the only safe way to compare source records between different Data Releases in general is to check the records of proximal source(s) in the same small part of the sky. This table provides the means to do this via a precomputed crossmatch of such sources, taking into account the proper motions available at E/DR3. Within the neighbourhood of a given E/DR3 source there may be none, one or (rarely) several possible counterparts in DR2 indicated by rows in this table. This occasional source confusion is an inevitable consequence of the merging, splitting and deletion of identifiers introduced in previous releases during the DR3 processing and results in no guaranteed one–to–one correspondence in source identifiers between the releases. For more details of the procedure used to create this crossmatch, see Chapter [chap:archive] in the online documentation.', 5, 2113601284, NULL, '(solo en el Archivo Gaia; bulk en https://cdn.gea.esac.esa.int/?prefix=Gaia/gedr3/)');
INSERT INTO meta_catalogo_tablas VALUES ('Cross-match', 'Cruce con catálogos externos', 'gaiadr3', 'gsc23_best_neighbour', 'TAP Gaia (ADQL)', '<p>GSC2.3 BestNeighbour table lists each matched Gaia object with its best neighbour in the external catalogue. The cross-match algorithm is not symmetric and searches Gaia sources counterparts in GSC2.3.<br/> The best neighbour is chosen among good neighbours as the one with the highest value of the figure of merit, which evaluates the ratio between two opposite models/hypotheses: the counterpart candidate is a match or it is found by chance. Good neighbours are nearby objects in the external catalogue whose position is compatible within position errors with the Gaia target.<br/> The cross-match algorithm is positional and exploits the full 5 parameters covariance matrix of Gaia astrometric solution when available and the external catalogue positions and position errors. In addition it takes into account the external catalogue environment using the local density.<br/> <br/> Please note that the cross-match algorithm is a trade-off between multiple requirements, in particular between completeness and correctness. It is thus not limited to a simple cone search.<br/> <br/> Reference papers:<br/> </p> <p>DR1-DPACP-17<br/> </p> <p>DR2-DPACP-41<br/> </p>', 7, 893811527, NULL, '(solo en el Archivo Gaia; bulk en https://cdn.gea.esac.esa.int/?prefix=Gaia/gedr3/)');
INSERT INTO meta_catalogo_tablas VALUES ('Cross-match', 'Cruce con catálogos externos', 'gaiadr3', 'gsc23_join', 'TAP Gaia (ADQL)', 'Convenience table to be used to join GSC 2.3 catalogue with the cross-match results. The table links the external catalogue original sourceId (originalExtSourceId) to the corresponding the additional numerical identifier (cleanGsc23Oid). Both originalExtSourceId and cleanGsc23Oid are present in the cross-match output tables (gsc23BestNeighbour and gsc23Neighbourhood). However, in case there are suspected duplicates in the external catalogue, different originalExtSourceId will correspond to the same cleanGsc23Oid. In the cross-match output table only the originalExtSourceId of the source with the best astrometry among the suspected duplicates will be listed. In practice, users may use the originalExtSourceId in the original catalogue to find the matching source with the best astrometry. Users interested to find all matching suspected duplicates should instead use the cleanGsc23Oid in the join with the cross-match result tables. See Documentation, [chap:crossmatch], for more details on the duplicates in the external catalogues and their treatment in the cross-match computations.', 2, 945592683, NULL, '(solo en el Archivo Gaia; bulk en https://cdn.gea.esac.esa.int/?prefix=Gaia/gedr3/)');
INSERT INTO meta_catalogo_tablas VALUES ('Cross-match', 'Cruce con catálogos externos', 'gaiadr3', 'gsc23_neighbourhood', 'TAP Gaia (ADQL)', '<p>GSC2.3 Neighbourhood table includes all good neighbours for each matched Gaia object. A good neighbour for a given Gaia source is a nearby object in the external catalogue whose position is compatible (within position errors) with the Gaia target. <br/> The cross-match algorithm is not symmetric and searches Gaia sources counterparts in GSC2.3. The cross-match algorithm is positional and exploits the full 5 parameters covariance matrix of Gaia astrometric solution when available and the external catalogue positions and position errors. In addition it takes into account the external catalogue environment using the local density.<br/> <br/> Please note that the cross-match algorithm is a trade-off between multiple requirements, in particular between completeness and correctness. It is thus not limited to a simple cone search.<br/> <br/> Reference papers:<br/> </p> <p>DR1-DPACP-17<br/> </p> <p>DR2-DPACP-41<br/> </p>', 6, 896358993, NULL, '(solo en el Archivo Gaia; bulk en https://cdn.gea.esac.esa.int/?prefix=Gaia/gedr3/)');
INSERT INTO meta_catalogo_tablas VALUES ('Cross-match', 'Cruce con catálogos externos', 'gaiadr3', 'hipparcos2_best_neighbour', 'TAP Gaia (ADQL)', '<p>Hipparcos2 BestNeighbour table lists each matched external catalogue object with its best neighbour in Gaia. The cross-match algorithm is not symmetric and searches Hipparcos2 sources counterparts in Gaia.<br/> The best neighbour is chosen among good neighbours as the one with the highest value of the figure of merit, which evaluates the ratio between two opposite models/hypotheses: the counterpart candidate is a match or it is found by chance. Good neighbours are nearby objects in Gaia whose position is compatible within position errors with the external catalogue target.<br/> The cross-match algorithm is positional and exploits the full 5 parameters covariance matrix of Gaia astrometric solution when available and the external catalogue positions and position errors. In addition it takes into account the Gaia environment using the local density.<br/> <br/> Please note that the cross-match algorithm is a trade-off between multiple requirements, in particular between completeness and correctness. It is thus not limited to a simple cone search.<br/> <br/> Reference papers:<br/> </p> <p>DR1-DPACP-17<br/> </p> <p>DR2-DPACP-41<br/> </p>', 5, 99525, NULL, '(solo en el Archivo Gaia; bulk en https://cdn.gea.esac.esa.int/?prefix=Gaia/gedr3/)');
INSERT INTO meta_catalogo_tablas VALUES ('Cross-match', 'Cruce con catálogos externos', 'gaiadr3', 'hipparcos2_neighbourhood', 'TAP Gaia (ADQL)', '<p>Hipparcos2 Neighbourhood table includes all good neighbours for each matched Hipparcos2 object. A good neighbour for a given Hipparcos2 source is a nearby Gaia object whose position is compatible (within position errors) with the Hipparcos2 target. <br/> The cross-match algorithm is not symmetric and searches Hipparcos2 sources counterparts in Gaia. The cross-match algorithm is positional and exploits the full 5 parameters covariance matrix of Gaia astrometric solution when available and the external catalogue positions and position errors. In addition it takes into account the Gaia environment using the local density.<br/> <br/> Please note that the cross-match algorithm is a trade-off between multiple requirements, in particular between completeness and correctness. It is thus not limited to a simple cone search.<br/> <br/> Reference papers:<br/> </p> <p>DR1-DPACP-17<br/> </p> <p>DR2-DPACP-41<br/> </p>', 5, 100010, NULL, '(solo en el Archivo Gaia; bulk en https://cdn.gea.esac.esa.int/?prefix=Gaia/gedr3/)');
INSERT INTO meta_catalogo_tablas VALUES ('Cross-match', 'Cruce con catálogos externos', 'gaiadr3', 'panstarrs1_best_neighbour', 'TAP Gaia (ADQL)', '<p>Pan-STARRS1 DR1 BestNeighbour table lists each matched Gaia object with its best neighbour in the external catalogue. The cross-match algorithm is not symmetric and searches Gaia sources counterparts in Pan-STARRS1 DR1.<br/> The best neighbour is chosen among good neighbours as the one with the highest value of the figure of merit, which evaluates the ratio between two opposite models/hypotheses: the counterpart candidate is a match or it is found by chance. Good neighbours are nearby objects in the external catalogue whose position is compatible within position errors with the Gaia target.<br/> The cross-match algorithm is positional and exploits the full 5 parameters covariance matrix of Gaia astrometric solution when available and the external catalogue positions and position errors. In addition it takes into account the external catalogue environment using the local density.<br/> <br/> Please note that the cross-match algorithm is a trade-off between multiple requirements, in particular between completeness and correctness. It is thus not limited to a simple cone search.<br/> <br/> Reference papers:<br/> </p> <p>DR1-DPACP-17<br/> </p> <p>DR2-DPACP-41<br/> </p>', 7, 951450474, NULL, '(solo en el Archivo Gaia; bulk en https://cdn.gea.esac.esa.int/?prefix=Gaia/gedr3/)');
INSERT INTO meta_catalogo_tablas VALUES ('Cross-match', 'Cruce con catálogos externos', 'gaiadr3', 'panstarrs1_join', 'TAP Gaia (ADQL)', 'Convenience table to be used to join Pan-STARRS1 DR1.1 catalogue with the cross-match results. The table links the external catalogue original sourceId (originalExtSourceId) to the corresponding the additional numerical identifier (cleanPanstarrs1Oid). Both originalExtSourceId and cleanPanstarrs1Oid are present in the cross-match output tables (panstarrs1BestNeighbour and panstarrs1Neighbourhood). However, in case there are suspected duplicates in the external catalogue, different originalExtSourceId will correspond to the same cleanPanstarrs1Oid. In the cross-match output table only the originalExtSourceId of the source with the best astrometry among the suspected duplicates will be listed. In practice, users may use the originalExtSourceId in the original catalogue to find the matching source with the best astrometry. Users interested to find all matching suspected duplicates should instead use the cleanPanstarrs1Oid in the join with the cross-match result tables. See Documentation, [chap:crossmatch], for more details on the duplicates in the external catalogues and their treatment in the cross-match computations.', 2, 2264263282, NULL, '(solo en el Archivo Gaia; bulk en https://cdn.gea.esac.esa.int/?prefix=Gaia/gedr3/)');
INSERT INTO meta_catalogo_tablas VALUES ('Cross-match', 'Cruce con catálogos externos', 'gaiadr3', 'panstarrs1_neighbourhood', 'TAP Gaia (ADQL)', '<p>Pan-STARRS1 DR1 Neighbourhood table includes all good neighbours for each matched Gaia object. A good neighbour for a given Gaia source is a nearby object in the external catalogue whose position is compatible (within position errors) with the Gaia target. <br/> The cross-match algorithm is not symmetric and searches Gaia sources counterparts in Pan-STARRS1 DR1. The cross-match algorithm is positional and exploits the full 5 parameters covariance matrix of Gaia astrometric solution when available and the external catalogue positions and position errors. In addition it takes into account the external catalogue environment using the local density.<br/> <br/> Please note that the cross-match algorithm is a trade-off between multiple requirements, in particular between completeness and correctness. It is thus not limited to a simple cone search.<br/> <br/> Reference papers:<br/> </p> <p>DR1-DPACP-17<br/> </p> <p>DR2-DPACP-41<br/> </p>', 6, 951850826, NULL, '(solo en el Archivo Gaia; bulk en https://cdn.gea.esac.esa.int/?prefix=Gaia/gedr3/)');
INSERT INTO meta_catalogo_tablas VALUES ('Cross-match', 'Cruce con catálogos externos', 'gaiadr3', 'ravedr5_best_neighbour', 'TAP Gaia (ADQL)', '<p>RAVE DR5 BestNeighbour table lists each matched external catalogue object with its best neighbour in Gaia. The cross-match algorithm is not symmetric and searches RAVE DR5 sources counterparts in Gaia.<br/> The best neighbour is chosen among good neighbours as the one with the highest value of the figure of merit, which evaluates the ratio between two opposite models/hypotheses: the counterpart candidate is a match or it is found by chance. Good neighbours are nearby objects in Gaia whose position is compatible within position errors with the external catalogue target.<br/> The cross-match algorithm is positional and exploits the full 5 parameters covariance matrix of Gaia astrometric solution when available and the external catalogue positions and position errors. In addition it takes into account the Gaia environment using the local density.<br/> <br/> Please note that the cross-match algorithm is a trade-off between multiple requirements, in particular between completeness and correctness. It is thus not limited to a simple cone search.<br/> <br/> Reference papers:<br/> </p> <p>DR1-DPACP-17<br/> </p> <p>DR2-DPACP-41<br/> </p>', 6, 450659, NULL, '(solo en el Archivo Gaia; bulk en https://cdn.gea.esac.esa.int/?prefix=Gaia/gedr3/)');
INSERT INTO meta_catalogo_tablas VALUES ('Cross-match', 'Cruce con catálogos externos', 'gaiadr3', 'ravedr5_join', 'TAP Gaia (ADQL)', 'Convenience table to be used to join RAVE DR5 catalogue with the cross-match results. The table links the external catalogue original sourceId (originalExtSourceId) to the corresponding the additional numerical identifier (cleanRavedr5Oid). Both originalExtSourceId and cleanRavedr5Oid are present in the cross-match output tables (ravedr5BestNeighbour and ravedr5Neighbourhood). However, in case there are suspected duplicates in the external catalogue, different originalExtSourceId will correspond to the same cleanRavedr5Oid. In the cross-match output table only the originalExtSourceId of the source with the best astrometry among the suspected duplicates will be listed. In practice, users may use the originalExtSourceId in the original catalogue to find the matching source with the best astrometry. Users interested to find all matching suspected duplicates should instead use the cleanRavedr5Oid in the join with the cross-match result tables. See Documentation, [chap:crossmatch], for more details on the duplicates in the external catalogues and their treatment in the cross-match computations.', 2, 457555, NULL, '(solo en el Archivo Gaia; bulk en https://cdn.gea.esac.esa.int/?prefix=Gaia/gedr3/)');
INSERT INTO meta_catalogo_tablas VALUES ('Cross-match', 'Cruce con catálogos externos', 'gaiadr3', 'ravedr5_neighbourhood', 'TAP Gaia (ADQL)', '<p>RAVE DR5 Neighbourhood table includes all good neighbours for each matched RAVE DR5 object. A good neighbour for a given RAVE DR5 source is a nearby Gaia object whose position is compatible (within position errors) with the RAVE DR5 target. <br/> The cross-match algorithm is not symmetric and searches RAVE DR5 sources counterparts in Gaia. The cross-match algorithm is positional and exploits the full 5 parameters covariance matrix of Gaia astrometric solution when available and the external catalogue positions and position errors. In addition it takes into account the Gaia environment using the local density.<br/> <br/> Please note that the cross-match algorithm is a trade-off between multiple requirements, in particular between completeness and correctness. It is thus not limited to a simple cone search.<br/> <br/> Reference papers:<br/> </p> <p>DR1-DPACP-17<br/> </p> <p>DR2-DPACP-41<br/> </p>', 6, 456422, NULL, '(solo en el Archivo Gaia; bulk en https://cdn.gea.esac.esa.int/?prefix=Gaia/gedr3/)');
INSERT INTO meta_catalogo_tablas VALUES ('Cross-match', 'Cruce con catálogos externos', 'gaiadr3', 'ravedr6_best_neighbour', 'TAP Gaia (ADQL)', 'Table {\tt Ravedr6BestNeighbour} lists each matched external catalogue object with its best neighbour in Gaia. The cross-match algorithm is not symmetric and searches RAVE DR6 sources counterparts in Gaia. The best neighbour is chosen among good neighbours as the one with the highest value of the figure of merit, which evaluates the ratio between two opposite models/hypotheses: the counterpart candidate is a match or it is found by chance. Good neighbours are nearby objects in Gaia whose position is compatible within position errors with the external catalogue target. The cross-match algorithm is positional and exploits the full~5 parameter covariance matrix of the Gaia astrometric solution when available and the external catalogue positions and position errors. In addition it takes into account the Gaia environment using the local density. Please note that the cross-match algorithm is a trade-off between multiple requirements, in particular between completeness and correctness. It is thus not limited to a simple cone search. Reference papers:\\ \citet{DR1-DPACP-17}\\ \citet{DR2-DPACP-41}\\', 6, 450597, 0.01, 'https://cdn.gea.esac.esa.int/?prefix=Gaia/gdr3/Cross-match/ravedr6_best_neighbour/');
INSERT INTO meta_catalogo_tablas VALUES ('Cross-match', 'Cruce con catálogos externos', 'gaiadr3', 'ravedr6_join', 'TAP Gaia (ADQL)', 'Convenience table to be used to join RAVE DR6 catalogue with the cross-match results. The table links the external catalogue original sourceId ({\tt originalExtSourceId}) to the corresponding additional numerical identifier ({\tt ravedr6Oid}). Both {\tt originalExtSourceId} and {\tt ravedr6Oid} are present in the cross-match output tables ({\tt Ravedr6BestNeighbour} and {\tt Ravedr6Neighbourhood}). However, in case there are suspected duplicates in the external catalogue, different {\tt originalExtSourceId} will correspond to the same {\tt ravedr6Oid}. In the cross-match output table only the {\tt originalExtSourceId} of the source with the best astrometry among the suspected duplicates will be listed. In practice, users may use the {\tt originalExtSourceId} in the original catalogue to find the matching source with the best astrometry. Users interested to find all matching suspected duplicates should instead use the {\tt ravedr6Oid} in the join with the cross-match result tables. See Chapter~\ref{chap:crossmatch}, for more details on the duplicates in the external catalogues and their treatment in the cross-match computations.', 2, 518387, 0.003, 'https://cdn.gea.esac.esa.int/?prefix=Gaia/gdr3/Cross-match/ravedr6_join/');
INSERT INTO meta_catalogo_tablas VALUES ('Cross-match', 'Cruce con catálogos externos', 'gaiadr3', 'ravedr6_neighbourhood', 'TAP Gaia (ADQL)', 'Table {\tt Ravedr6Neighbourhood} includes all good neighbours for each matched RAVE DR6 object. A good neighbour for a given RAVE DR6 source is a nearby Gaia object whose position is compatible (within position errors) with the RAVE DR6 target. The cross-match algorithm is not symmetric and searches RAVE DR6 sources counterparts in Gaia. The cross-match algorithm is positional and exploits the full~5 parameter covariance matrix of the Gaia astrometric solution when available and the external catalogue positions and position errors. In addition it takes into account the Gaia environment using the local density. Please note that the cross-match algorithm is a trade-off between multiple requirements, in particular between completeness and correctness. It is thus not limited to a simple cone search. Reference papers:\\ \citet{DR1-DPACP-17}\\ \citet{DR2-DPACP-41}\\', 6, 456370, 0.015, 'https://cdn.gea.esac.esa.int/?prefix=Gaia/gdr3/Cross-match/ravedr6_neighbourhood/');
INSERT INTO meta_catalogo_tablas VALUES ('Cross-match', 'Cruce con catálogos externos', 'gaiadr3', 'sdssdr13_best_neighbour', 'TAP Gaia (ADQL)', '<p>SDSS DR13 BestNeighbour table lists each matched Gaia object with its best neighbour in the external catalogue. The cross-match algorithm is not symmetric and searches Gaia sources counterparts in SDSS DR13.<br/> The best neighbour is chosen among good neighbours as the one with the highest value of the figure of merit, which evaluates the ratio between two opposite models/hypotheses: the counterpart candidate is a match or it is found by chance. Good neighbours are nearby objects in the external catalogue whose position is compatible within position errors with the Gaia target.<br/> The cross-match algorithm is positional and exploits the full 5 parameters covariance matrix of Gaia astrometric solution when available and the external catalogue positions and position errors. In addition it takes into account the external catalogue environment using the local density.<br/> <br/> Please note that the cross-match algorithm is a trade-off between multiple requirements, in particular between completeness and correctness. It is thus not limited to a simple cone search.<br/> <br/> Reference papers:<br/> </p> <p>DR1-DPACP-17<br/> </p> <p>DR2-DPACP-41<br/> </p>', 7, 128130925, NULL, '(solo en el Archivo Gaia; bulk en https://cdn.gea.esac.esa.int/?prefix=Gaia/gedr3/)');
INSERT INTO meta_catalogo_tablas VALUES ('Cross-match', 'Cruce con catálogos externos', 'gaiadr3', 'sdssdr13_join', 'TAP Gaia (ADQL)', 'Convenience table to be used to join SDSS DR13 catalogue with the cross-match results. The table links the external catalogue original sourceId (originalExtSourceId) to the corresponding the additional numerical identifier (sdssdr13Oid). Both originalExtSourceId and sdssdr13Oid are present in the cross-match output tables (sdssdr13BestNeighbour and sdssdr13Neighbourhood). However, in case there are suspected duplicates in the external catalogue, different originalExtSourceId will correspond to the same sdssdr13Oid. In the cross-match output table only the originalExtSourceId of the source with the best astrometry among the suspected duplicates will be listed. In practice, users may use the originalExtSourceId in the original catalogue to find the matching source with the best astrometry. Users interested to find all matching suspected duplicates should instead use the sdssdr13Oid in the join with the cross-match result tables. See Documentation [chap:crossmatch], for more details on the duplicates in the external catalogues and their treatment in the cross-match computations.', 2, 468180930, NULL, '(solo en el Archivo Gaia; bulk en https://cdn.gea.esac.esa.int/?prefix=Gaia/gedr3/)');
INSERT INTO meta_catalogo_tablas VALUES ('Cross-match', 'Cruce con catálogos externos', 'gaiadr3', 'sdssdr13_neighbourhood', 'TAP Gaia (ADQL)', '<p>SDSS DR13 Neighbourhood table includes all good neighbours for each matched Gaia object. A good neighbour for a given Gaia source is a nearby object in the external catalogue whose position is compatible (within position errors) with the Gaia target. <br/> The cross-match algorithm is not symmetric and searches Gaia sources counterparts in SDSS DR13. The cross-match algorithm is positional and exploits the full 5 parameters covariance matrix of Gaia astrometric solution when available and the external catalogue positions and position errors. In addition it takes into account the external catalogue environment using the local density.<br/> <br/> Please note that the cross-match algorithm is a trade-off between multiple requirements, in particular between completeness and correctness. It is thus not limited to a simple cone search.<br/> <br/> Reference papers:<br/> </p> <p>DR1-DPACP-17<br/> </p> <p>DR2-DPACP-41<br/> </p>', 6, 128251974, NULL, '(solo en el Archivo Gaia; bulk en https://cdn.gea.esac.esa.int/?prefix=Gaia/gedr3/)');
INSERT INTO meta_catalogo_tablas VALUES ('Cross-match', 'Cruce con catálogos externos', 'gaiadr3', 'skymapperdr2_best_neighbour', 'TAP Gaia (ADQL)', '<p>SkyMapper DR2 BestNeighbour table lists each matched Gaia object with its best neighbour in the external catalogue. The cross-match algorithm is not symmetric and searches Gaia sources counterparts in SkyMapper DR2.<br/> The best neighbour is chosen among good neighbours as the one with the highest value of the figure of merit, which evaluates the ratio between two opposite models/hypotheses: the counterpart candidate is a match or it is found by chance. Good neighbours are nearby objects in the external catalogue whose position is compatible within position errors with the Gaia target.<br/> The cross-match algorithm is positional and exploits the full 5 parameters covariance matrix of Gaia astrometric solution when available and the external catalogue positions and position errors. In addition it takes into account the external catalogue environment using the local density.<br/> <br/> Please note that the cross-match algorithm is a trade-off between multiple requirements, in particular between completeness and correctness. It is thus not limited to a simple cone search.<br/> <br/> Reference papers:<br/> </p> <p>DR1-DPACP-17<br/> </p> <p>DR2-DPACP-41<br/> </p>', 6, 446161579, NULL, '(solo en el Archivo Gaia; bulk en https://cdn.gea.esac.esa.int/?prefix=Gaia/gedr3/)');
INSERT INTO meta_catalogo_tablas VALUES ('Cross-match', 'Cruce con catálogos externos', 'gaiadr3', 'skymapperdr2_join', 'TAP Gaia (ADQL)', 'Convenience table to be used to join SkyMapper DR2 catalogue with the cross-match results. It lists all the SkyMapper DR2 sources which were used in the cross-match. See Documentation, [chap:crossmatch], for more details on the catalogue.', 1, 504910161, NULL, '(solo en el Archivo Gaia; bulk en https://cdn.gea.esac.esa.int/?prefix=Gaia/gedr3/)');
INSERT INTO meta_catalogo_tablas VALUES ('Cross-match', 'Cruce con catálogos externos', 'gaiadr3', 'skymapperdr2_neighbourhood', 'TAP Gaia (ADQL)', '<p>SkyMapper DR2 Neighbourhood table includes all good neighbours for each matched Gaia object. A good neighbour for a given Gaia source is a nearby object in the external catalogue whose position is compatible (within position errors) with the Gaia target. <br/> The cross-match algorithm is not symmetric and searches Gaia sources counterparts in SkyMapper DR2. The cross-match algorithm is positional and exploits the full 5 parameters covariance matrix of Gaia astrometric solution when available and the external catalogue positions and position errors. In addition it takes into account the external catalogue environment using the local density.<br/> <br/> Please note that the cross-match algorithm is a trade-off between multiple requirements, in particular between completeness and correctness. It is thus not limited to a simple cone search.<br/> <br/> Reference papers:<br/> </p> <p>DR1-DPACP-17<br/> </p> <p>DR2-DPACP-41<br/> </p>', 5, 446297242, NULL, '(solo en el Archivo Gaia; bulk en https://cdn.gea.esac.esa.int/?prefix=Gaia/gedr3/)');
INSERT INTO meta_catalogo_tablas VALUES ('Cross-match', 'Cruce con catálogos externos', 'gaiadr3', 'tmass_psc_xsc_best_neighbour', 'TAP Gaia (ADQL)', '<p>2MASS BestNeighbour table lists each matched Gaia object with its best neighbour in the external catalogue. The cross-match algorithm is not symmetric and searches Gaia sources counterparts in 2MASS.<br/> The best neighbour is chosen among good neighbours as the one with the highest value of the figure of merit, which evaluates the ratio between two opposite models/hypotheses: the counterpart candidate is a match or it is found by chance. Good neighbours are nearby objects in the external catalogue whose position is compatible within position errors with the Gaia target.<br/> The cross-match algorithm is positional and exploits the full 5 parameters covariance matrix of Gaia astrometric solution when available and the external catalogue positions and position errors. In addition it takes into account the external catalogue environment using the local density.<br/> <br/> Please note that the cross-match algorithm is a trade-off between multiple requirements, in particular between completeness and correctness. It is thus not limited to a simple cone search.<br/> <br/> Reference papers:<br/> </p> <p>DR1-DPACP-17<br/> </p> <p>DR2-DPACP-41<br/> </p>', 7, 469051627, NULL, '(solo en el Archivo Gaia; bulk en https://cdn.gea.esac.esa.int/?prefix=Gaia/gedr3/)');
INSERT INTO meta_catalogo_tablas VALUES ('Cross-match', 'Cruce con catálogos externos', 'gaiadr3', 'tmass_psc_xsc_join', 'TAP Gaia (ADQL)', 'Convenience table to be used to join 2MASS PSC+XSC catalogue with the cross-match results. The table links the external catalogue original sourceId (originalExtSourceId) to the corresponding the additional numerical identifier (cleanTmassPscXscOid). Both originalExtSourceId and cleanTmassPscXscOid are present in the cross-match output tables (tmassPscXscBestNeighbour and tmassPscXscNeighbourhood). However, in case there are suspected duplicates in the external catalogue, different originalExtSourceId will correspond to the same cleanTmassPscXscOid. In the cross-match output table only the originalExtSourceId of the source with the best astrometry among the suspected duplicates will be listed. In practice, users may use the originalExtSourceId in the original catalogue to find the matching source with the best astrometry. Users interested to find all matching suspected duplicates should instead use the cleanTmassPscXscOid in the join with the cross-match result tables. See Documentation, [chap:crossmatch], for more details on the duplicates in the external catalogues and their treatment in the cross-match computations.', 3, 471063502, NULL, '(solo en el Archivo Gaia; bulk en https://cdn.gea.esac.esa.int/?prefix=Gaia/gedr3/)');
INSERT INTO meta_catalogo_tablas VALUES ('Cross-match', 'Cruce con catálogos externos', 'gaiadr3', 'tmass_psc_xsc_neighbourhood', 'TAP Gaia (ADQL)', '<p>2MASS Neighbourhood table includes all good neighbours for each matched Gaia object. A good neighbour for a given Gaia source is a nearby object in the external catalogue whose position is compatible (within position errors) with the Gaia target. <br/> The cross-match algorithm is not symmetric and searches Gaia sources counterparts in 2MASS. The cross-match algorithm is positional and exploits the full 5 parameters covariance matrix of Gaia astrometric solution when available and the external catalogue positions and position errors. In addition it takes into account the external catalogue environment using the local density.<br/> <br/> Please note that the cross-match algorithm is a trade-off between multiple requirements, in particular between completeness and correctness. It is thus not limited to a simple cone search.<br/> <br/> Reference papers:<br/> </p> <p>DR1-DPACP-17<br/> </p> <p>DR2-DPACP-41<br/> </p>', 6, 469600014, NULL, '(solo en el Archivo Gaia; bulk en https://cdn.gea.esac.esa.int/?prefix=Gaia/gedr3/)');
INSERT INTO meta_catalogo_tablas VALUES ('Cross-match', 'Cruce con catálogos externos', 'gaiadr3', 'tycho2tdsc_merge', 'TAP Gaia (ADQL)', 'Tycho-2 merged with the TDSC catalog and TDSC supplement. The Tycho Double Star Catalogue, (TDSC, ) contains 98482 components of double and multiple systems processed in the Tycho-2 context. It includes either original Tycho-2 data or results from a dedicated re-processing aimed at binaries. As pointed out by P. Marrese (personal communication), the TDSC star with identifier 29583 is redundant and it was therefore skipped. The TDSC supplement contains data from an additional 4777 components from either Hipparcos or Tycho-1. The Tycho-2 main catalogue contains 2539913 sources, including many binaries, but a minimum separation of 0.8 arcsec was imposed during the catalogue construction. The Tycho-2 supplement-1 contains data for 17588 Hipparcos and Tycho-1 stars, which do not appear in the main catalogue, but only the 4777 stars relevant for TDSC are included here. The Tycho-2 supplement-2 contains an additional 1146 Tycho-1 stars of poor quality. We have merged Tycho-2 (main) with the TDSC main and supplement, keeping the Tycho-2 data model and extending it to include TDSC–specific fields. This is only possible to a certain degree as specified in detail below. In particular, Tycho-2 includes fields for mean position, proper motion etc. for a combination of Tycho-2 and several ground based catalogues. These fields are inherited for TDSC main stars, but were not derived for the TDSC supplement, where we only provide HIP proper motions. For Tycho-2 stars not in TDSC, blank TDSC fields were appended. For Tycho-2 stars in TDSC, the following fields were replaced by the corresponding TDSC fields: - tyc1, tyc2, tyc3; - hip; - ccdm. In addition, if the TDSC contains a new solution: - btMag, eBtMag, vtMag, eVtMag, raDeg, deDeg, epRa1990, epDe1990, eRaDeg, eDeDec; - The mean position flag, pflag, is set to ‘P’ (“photocentre") if resolved and there are Tycho-2 mean positions. Mean position etc. are then repeated for both new components; - The proximity indicator, prox, is set to blank if the Tycho-2 star was resolved in TDSC; - The type-of-solution flag, posflg, set to ‘N’; - For resolved Tycho-2 stars, two records are given. For the few TDSC stars with new solutions, but not in Tycho-2, and for the TDSC supplement stars (Hipparcos or Tycho-1), the Tycho-2 part of the merged record was populated in the following way: - TYC1..3 from TDSC; - pflag set to TDSC pmflg (‘H’ or ‘X’), ‘H’ indicating Hip proper motions; - no mean position and related fields; - proper motions only for Hipparcos stars; - $B_{\rm T}, V_{\rm T}$ photometry from TDSC; - Tycho-1 flag, tyc, is set to posflg, i.e. ‘T’ or ‘H’ although Hipparcos stars may well be in Tycho-1; - Hipparcos, hip, and CCDM, ccdm, identifiers from TDSC; - astrometry from TDSC, but the (ra, dec)-correlation, corr, is set to blank. New TDSC specific fields added after the Tycho-2 part of the record: - sysNo, cmp, nMain, nSup, magflg, wds, note, hd; - rcmp, pa, sep, ePa, ePaSep, eSep.', 53, 2561887, NULL, '(solo en el Archivo Gaia; bulk en https://cdn.gea.esac.esa.int/?prefix=Gaia/gedr3/)');
INSERT INTO meta_catalogo_tablas VALUES ('Cross-match', 'Cruce con catálogos externos', 'gaiadr3', 'tycho2tdsc_merge_best_neighbour', 'TAP Gaia (ADQL)', '<p>Tycho2TDSCmerge BestNeighbour table lists each matched external catalogue object with its best neighbour in Gaia. The cross-match algorithm is not symmetric and searches Tycho2TDSCmerge sources counterparts in Gaia.<br/> The best neighbour is chosen among good neighbours as the one with the highest value of the figure of merit, which evaluates the ratio between two opposite models/hypotheses: the counterpart candidate is a match or it is found by chance. Good neighbours are nearby objects in Gaia whose position is compatible within position errors with the external catalogue target.<br/> The cross-match algorithm is positional and exploits the full 5 parameters covariance matrix of Gaia astrometric solution when available and the external catalogue positions and position errors. In addition it takes into account the Gaia environment using the local density.<br/> <br/> Please note that the cross-match algorithm is a trade-off between multiple requirements, in particular between completeness and correctness. It is thus not limited to a simple cone search.<br/> <br/> Reference papers:<br/> </p> <p>DR1-DPACP-17<br/> </p> <p>DR2-DPACP-41<br/> </p>', 6, 2518330, NULL, '(solo en el Archivo Gaia; bulk en https://cdn.gea.esac.esa.int/?prefix=Gaia/gedr3/)');
