INSERT INTO meta_catalogo_tablas VALUES ('Cross-match', 'Cruce con catálogos externos', 'gaiadr3', 'urat1_best_neighbour', 'TAP Gaia (ADQL)', '<p>URAT-1 BestNeighbour table lists each matched Gaia object with its best neighbour in the external catalogue. The cross-match algorithm is not symmetric and searches Gaia sources counterparts in URAT-1.<br/> The best neighbour is chosen among good neighbours as the one with the highest value of the figure of merit, which evaluates the ratio between two opposite models/hypotheses: the counterpart candidate is a match or it is found by chance. Good neighbours are nearby objects in the external catalogue whose position is compatible within position errors with the Gaia target.<br/> The cross-match algorithm is positional and exploits the full 5 parameters covariance matrix of Gaia astrometric solution when available and the external catalogue positions and position errors. In addition it takes into account the external catalogue environment using the local density.<br/> <br/> Please note that the cross-match algorithm is a trade-off between multiple requirements, in particular between completeness and correctness. It is thus not limited to a simple cone search.<br/> <br/> Reference papers:<br/> </p> <p>DR1-DPACP-17<br/> </p> <p>DR2-DPACP-41<br/> </p>', 7, 227682906, NULL, '(solo en el Archivo Gaia; bulk en https://cdn.gea.esac.esa.int/?prefix=Gaia/gedr3/)');
INSERT INTO meta_catalogo_tablas VALUES ('Cross-match', 'Cruce con catálogos externos', 'gaiadr3', 'urat1_neighbourhood', 'TAP Gaia (ADQL)', '<p>URAT-1 Neighbourhood table includes all good neighbours for each matched Gaia object. A good neighbour for a given Gaia source is a nearby object in the external catalogue whose position is compatible (within position errors) with the Gaia target. <br/> The cross-match algorithm is not symmetric and searches Gaia sources counterparts in URAT-1. The cross-match algorithm is positional and exploits the full 5 parameters covariance matrix of Gaia astrometric solution when available and the external catalogue positions and position errors. In addition it takes into account the external catalogue environment using the local density.<br/> <br/> Please note that the cross-match algorithm is a trade-off between multiple requirements, in particular between completeness and correctness. It is thus not limited to a simple cone search.<br/> <br/> Reference papers:<br/> </p> <p>DR1-DPACP-17<br/> </p> <p>DR2-DPACP-41<br/> </p>', 6, 227683310, NULL, '(solo en el Archivo Gaia; bulk en https://cdn.gea.esac.esa.int/?prefix=Gaia/gedr3/)');
INSERT INTO meta_catalogo_tablas VALUES ('Extra-galactic', 'Extragaláctico', 'gaiadr3', 'galaxy_candidates', 'TAP Gaia (ADQL)', 'This table contains parameters derived from various modules dedicated to the classification and characterisation of sources considered as galaxy candidates. This table has been constructed with the intention to be complete rather than pure and, as such, it will contain a large fraction of non-genuine extragalactic sources. Purer samples can be drawn using dedicated flags or queries. Please refer to Chapter~\ref{chap:cu3qso} of the on-line documentation for details about how this table was built, its content, and for recommendations regarding its exploitation.', 38, 4842342, 0.413, 'https://cdn.gea.esac.esa.int/?prefix=Gaia/gdr3/Extra-galactic/galaxy_candidates/');
INSERT INTO meta_catalogo_tablas VALUES ('Extra-galactic', 'Extragaláctico', 'gaiadr3', 'galaxy_catalogue_name', 'TAP Gaia (ADQL)', 'This table provides the list of input catalogues that have been used to select any given source for which morphological analysis parameters are provided in table {\tt GalaxyCandidates}. Each source may have been cross-matched to more than one catalogue and therefore can have several entries in the table. For DR3, the catalogues considered for this selection are mostly external, although sources identified by DPAC based on the classification performed by other processing have also been included here. Each catalogue is assigned a \texttt{catalogueId}. For DR3 the only input list corresponds to that published in~\cite{2022Krone-Martins}. Further details on these catalogues are given in the chapter on extended object processing (Section~\ref{sec:cu4eo_list}).', 3, 914837, 0.01, 'https://cdn.gea.esac.esa.int/?prefix=Gaia/gdr3/Extra-galactic/galaxy_catalogue_name/');
INSERT INTO meta_catalogo_tablas VALUES ('Extra-galactic', 'Extragaláctico', 'gaiadr3', 'qso_candidates', 'TAP Gaia (ADQL)', 'This table contains parameters derived from various modules dedicated to the classification and characterisation of sources considered as QSO candidates. Together with those, the QSOs used to define the Gaia-CRF3 are also listed in this table. This table has been constructed with the intention to be complete rather than pure and, as such, it will contain a large fraction of non-genuine extragalactic sources. Purer samples can be drawn using dedicated flags or queries. Please refer to Chapter~\ref{chap:cu3qso} of the on-line documentation for details about how this table was built, its content, and for recommendations regarding its exploitation.', 41, 6649162, 0.373, 'https://cdn.gea.esac.esa.int/?prefix=Gaia/gdr3/Extra-galactic/qso_candidates/');
INSERT INTO meta_catalogo_tablas VALUES ('Extra-galactic', 'Extragaláctico', 'gaiadr3', 'qso_catalogue_name', 'TAP Gaia (ADQL)', 'This table provides the list of input catalogues that have been used to select any given source for which morphological analysis parameters are provided in table \texttt{QsoCandidates}. Each source may have been cross-matched to more than one catalogue and therefore can have several entries in the table. For DR3, the catalogues considered for this selection are mostly external, although sources identified by DPAC based on the classification performed by other processing have also been included here. Each catalogue is assigned a \texttt{catalogueId}. For DR3 the following applies: \begin{itemize} \item 1: CU7 GaiaVariQso2018 \item 2: ICRF2 \item 3: SDSS-DR12Q \item 4: LQAC3 \item 5: Half Million Quasars \item 6: Secrest+2015 \item 7: Assef+2018\_R90 \end{itemize} Further details on these catalogues are given in the chapter on extended object processing (\secref{sec:cu4eo_list}).', 3, 2722093, 0.019, 'https://cdn.gea.esac.esa.int/?prefix=Gaia/gdr3/Extra-galactic/qso_catalogue_name/');
INSERT INTO meta_catalogo_tablas VALUES ('Non-single_stars', 'Estrellas no simples (binarias)', 'gaiadr3', 'nss_acceleration_astro', 'TAP Gaia (ADQL)', 'This table contains non-single-star astrometric models for sources having a non-linear proper motion which is compatible with an acceleration solution. Several possible models are hosted within the same table and they are indicated by the field \texttt{nssSolutionType}. The description of this latter lists all possible solution types considered for this release. Only a selection of parameters hosted in this table are provided here, depending on the solution. The details of those is given in the description of field \texttt{bitIndex}, which can also be used to extract the relevant elements of the correlation vector \texttt{corrVec}. Details about the formalism used to derive the parameters in this table are given in the on-line documentation, see Chapter~\ref{chap:cu4nss}.', 29, 338215, 0.09, 'https://cdn.gea.esac.esa.int/?prefix=Gaia/gdr3/Non-single_stars/nss_acceleration_astro/');
INSERT INTO meta_catalogo_tablas VALUES ('Non-single_stars', 'Estrellas no simples (binarias)', 'gaiadr3', 'nss_non_linear_spectro', 'TAP Gaia (ADQL)', 'This table contains non-single-star orbital models for spectroscopic binaries compatible with a trend. Several possible models are hosted within the same table and they are indicated by the field \texttt{nssSolutionType}. The description of this latter lists all possible solution types considered for this release. Only a selection of parameters hosted in this table are provided here, depending on the solution. The details of those is given in the description of field \texttt{bitIndex}, which can also be used to extract the relevant elements of the correlation vector \texttt{corrVec}. Details about the formalism used to derive the parameters in this table are given in the on-line documentation, see Chapter~\ref{chap:cu4nss}.', 16, 56808, 0.004, 'https://cdn.gea.esac.esa.int/?prefix=Gaia/gdr3/Non-single_stars/nss_non_linear_spectro/');
INSERT INTO meta_catalogo_tablas VALUES ('Non-single_stars', 'Estrellas no simples (binarias)', 'gaiadr3', 'nss_two_body_orbit', 'TAP Gaia (ADQL)', 'This table contains non-single-star orbital models for sources compatible with an orbital two-body solution. This covers astrometric binaries, spectroscopic binaries, eclipsing binaries and certain combinations thereof. Several possible models are hosted within the same table and they are indicated by the field \texttt{nssSolutionType}. The description of this latter lists all possible solution types considered for this release. Only a selection of parameters hosted in this table are provided here, depending on the solution. The details of those is given in the description of field \texttt{bitIndex}, which can also be used to extract the relevant elements of the correlation vector \texttt{corrVec}. Details about the formalism used to derive the parameters in this table are given in the on-line documentation, see Chapter~\ref{chap:cu4nss}. Warning: as a source may receive independent astrometric, spectroscopic or photometric orbits, a query using a given sourceId may return several solutions. This has to be accounted for when doing a crossmatch by sourceId.', 77, 443205, 0.167, 'https://cdn.gea.esac.esa.int/?prefix=Gaia/gdr3/Non-single_stars/nss_two_body_orbit/');
INSERT INTO meta_catalogo_tablas VALUES ('Non-single_stars', 'Estrellas no simples (binarias)', 'gaiadr3', 'nss_vim_fl', 'TAP Gaia (ADQL)', 'This table contains non-single-star models for sources compatible with an Variability Induced Mover (VIM) solution. Several possible models are in principle hosted within the same table and they are indicated by the field \texttt{nssSolutionType}. The description of this latter lists all possible solution types considered for this release. Only a selection of parameters hosted in this table are provided here, depending on the solution. The details of those is given in the description of field \texttt{bitIndex}, which can also be used to extract the relevant elements of the correlation vector \texttt{corrVec}. For DR3, only VIMF solutions are provided here. Details about the formalism used to derive the parameters in this table are given in the on-line documentation, see Chapter~\ref{chap:cu4nss}.', 27, 870, 0.0, 'https://cdn.gea.esac.esa.int/?prefix=Gaia/gdr3/Non-single_stars/nss_vim_fl/');
INSERT INTO meta_catalogo_tablas VALUES ('Performance_verification', 'Verificación de rendimiento', 'gaiadr3', 'binary_masses', 'TAP Gaia (ADQL)', 'Masses derived from the non-single stars (NSS) solutions with orbital parameters in table {\tt gaiadr3.nss\_two\_body\_orbit}. The table below is described in detail in \cite{DR3-DPACP-100}. The table presents the different types of NSS orbital solutions combined and which parameters each combination allows to constrain: \begin{tabular}{llccc} \hline\hline {\tt combinationMethod} & {\tt m1} & {\tt m2} & {\tt fluxratio} \\ \hline Orbital+SB2 & \checkmark & \checkmark & \checkmark \\ EclipsingSpectro(SB2) & \checkmark & \checkmark & \\ Eclipsing+SB2 & \checkmark & \checkmark & \\ AstroSpectroSB1+M1 & & \checkmark & \checkmark \\ Orbital+SB1+M1 & & \checkmark & \checkmark \\ EclipsingSpectro+M1 & & \checkmark & \\ Eclipsing+SB1+M1 & & \checkmark & \\ SB2+M1 & & \checkmark & \\ Orbital+M1 & & lower/upper & \\ SB1+M1 & & lower & \\ \hline \end{tabular}', 13, 195315, 0.007, 'https://cdn.gea.esac.esa.int/?prefix=Gaia/gdr3/Performance_verification/binary_masses/');
INSERT INTO meta_catalogo_tablas VALUES ('Performance_verification', 'Verificación de rendimiento', 'gaiadr3', 'chemical_cartography', 'TAP Gaia (ADQL)', 'Orbital parameters, actions, Galactocentric Cartesian coordinates and velocities for the sample of stars used in the DR3 chemical cartographic study of the Milky Way. For further details see \cite{DR3-DPACP-104}.', 45, 5591594, 1.191, 'https://cdn.gea.esac.esa.int/?prefix=Gaia/gdr3/Performance_verification/chemical_cartography/');
INSERT INTO meta_catalogo_tablas VALUES ('Performance_verification', 'Verificación de rendimiento', 'gaiadr3', 'gold_sample_carbon_stars', 'TAP Gaia (ADQL)', 'List of \textit{Gaia} DR3 source IDs for carbon stars extracted from the main list of candidate carbon stars for having C2 and CN molecular bands significantly stronger than usual M stars \citep{DR3-DPACP-123}.', 1, 15740, 0.0, 'https://cdn.gea.esac.esa.int/?prefix=Gaia/gdr3/Performance_verification/gold_sample_carbon_stars/');
INSERT INTO meta_catalogo_tablas VALUES ('Performance_verification', 'Verificación de rendimiento', 'gaiadr3', 'gold_sample_fgkm_stars', 'TAP Gaia (ADQL)', 'Stellar astrophysical parameters of the golden sample of F, G, K, and M stars from \cite{DR3-DPACP-123}. Values are identical to the ones in the \texttt{astrophysical\_parameters} and \texttt{astrophysical\_parameters\_supp} tables, but only those values retained after filtering are copied over.', 21, 3273041, 0.156, 'https://cdn.gea.esac.esa.int/?prefix=Gaia/gdr3/Performance_verification/gold_sample_fgkm_stars/');
INSERT INTO meta_catalogo_tablas VALUES ('Performance_verification', 'Verificación de rendimiento', 'gaiadr3', 'gold_sample_oba_stars', 'TAP Gaia (ADQL)', 'List of \textit{Gaia} DR3 source IDs of O, B, and A-type stars having an effective temperature estimate provided by ESP-HS or/and GSP-Phot greater than 7\,500~K. Based on the information available in the \textit{Gaia} DR3 catalogue, various filters were applied in order to reduce as much as possible the pollution from other types of targets. See \cite{DR3-DPACP-123} for more details.', 2, 3023388, 0.024, 'https://cdn.gea.esac.esa.int/?prefix=Gaia/gdr3/Performance_verification/gold_sample_oba_stars/');
INSERT INTO meta_catalogo_tablas VALUES ('Performance_verification', 'Verificación de rendimiento', 'gaiadr3', 'gold_sample_solar_analogues', 'TAP Gaia (ADQL)', '\textit{Gaia} DR3 source IDs of candidates for solar analogues selected from GSP-Spec via effective temperature, surface gravity and metallicity and from FLAME via mass and radius. For more details please refer to \cite{DR3-DPACP-123}.', 1, 5863, 0.0, 'https://cdn.gea.esac.esa.int/?prefix=Gaia/gdr3/Performance_verification/gold_sample_solar_analogues/');
INSERT INTO meta_catalogo_tablas VALUES ('Performance_verification', 'Verificación de rendimiento', 'gaiadr3', 'gold_sample_spss', 'TAP Gaia (ADQL)', 'Recommended parameters for the Gaia Spectro-Photometric Standard stars \citep{2021MNRAS.503.3660P}, selected as described in \cite{DR3-DPACP-123}, from the available parameters produced by CU8 \citep{DR3-DPACP-157} and CU6 \citep{DR3-DPACP-159}.', 35, 111, 0.0, 'https://cdn.gea.esac.esa.int/?prefix=Gaia/gdr3/Performance_verification/gold_sample_spss/');
INSERT INTO meta_catalogo_tablas VALUES ('Performance_verification', 'Verificación de rendimiento', 'gaiadr3', 'gold_sample_ucd', 'TAP Gaia (ADQL)', 'The table contains the bolometric luminosities and radii in solar units for a subset of ultracool dwarfs from the Gaia DR3 catalogue, as well as some intermediate quantities used in the selection of sources and in the derivation of the luminosities and radii. For more details please refer to \cite{DR3-DPACP-123}.', 7, 21062, 0.001, 'https://cdn.gea.esac.esa.int/?prefix=Gaia/gdr3/Performance_verification/gold_sample_ucd/');
INSERT INTO meta_catalogo_tablas VALUES ('Performance_verification', 'Verificación de rendimiento', 'gaiadr3', 'sso_orbits', 'TAP Gaia (ADQL)', 'Orbital parameters and uncertainties computed from the {\tt sso\_observation} astrometric data. The content of the table is described in the DR3 publication \cite{DR3-DPACP-150}.', 15, 154741, 0.091, 'https://cdn.gea.esac.esa.int/?prefix=Gaia/gdr3/Performance_verification/sso_orbits/');
INSERT INTO meta_catalogo_tablas VALUES ('Performance_verification', 'Verificación de rendimiento', 'gaiadr3', 'synthetic_photometry_gspc', 'TAP Gaia (ADQL)', 'Gaia Synthetic Photometry Catalogue (GSPC) This is a catalogue of synthetic photometry generated from the Gaia BP/RP mean spectra in Data Release 3 and standardised using wide and reliable sets of external standard stars. Only sources that have BP/RP mean spectra in Gaia DR3 can be included in this catalogue. Individual magnitudes and fluxes are included only if $F/\sigma_F>30$ in that passband, where $F$ and $\sigma_F$ are the flux and its uncertainty. Synthetic photometry is provided in a selection of photometric systems. Further details on the generation and composition of the catalogue are available in \cite{DR3-DPACP-93}.', 54, 218936915, 41.977, 'https://cdn.gea.esac.esa.int/?prefix=Gaia/gdr3/Performance_verification/synthetic_photometry_gspc/');
INSERT INTO meta_catalogo_tablas VALUES ('Performance_verification', 'Verificación de rendimiento', 'gaiadr3', 'vari_spurious_signals', 'TAP Gaia (ADQL)', 'Several statistics computed for all sources with published photometric time series which can help in the identification of sources that are affected by calibration issues resulting in, for example, spurious variability signals. The table has a row for every source with {\tt GaiaSource.hasEpochPhotometry} set to TRUE and is described in detail in \cite{DR3-DPACP-164}.', 38, 11754237, 1.993, 'https://cdn.gea.esac.esa.int/?prefix=Gaia/gdr3/Performance_verification/vari_spurious_signals/');
INSERT INTO meta_catalogo_tablas VALUES ('Photometry', 'Fotometría por época', 'gaiadr3', 'epoch_photometry', 'DataLink (EPOCH_PHOTOMETRY)', 'Epoch photometry. Each row in this table contains the light curve for a given object in bands G, BP and RP as stored in the DataLink Massive data base. This table makes extensive use of array types. It can be obtained selecting the RAW data structure option. A flat table (sparse cube), which one photometric point per source per row can be obtained using INDIVIDUAL or COMBINED. Note this table is not available through the main archive TAP interface. Data are delivered via the Massive Data service indexed by the VO Datalink protocol and described in Chapter~\ref{chap:archive}. For example this can be actioned in the archive user interface by querying the main source catalogue {\tt GaiaSource} and selecting {\tt hasEpochPhotometry}~{\tt = ''t''}.', 48, NULL, 72.812, 'https://cdn.gea.esac.esa.int/?prefix=Gaia/gdr3/Photometry/epoch_photometry/');
INSERT INTO meta_catalogo_tablas VALUES ('Reference_frame', 'Marco de referencia', 'gaiadr3', 'agn_cross_id', 'TAP Gaia (ADQL)', '<p>Table <tt>AgnCrossId</tt> lists sources whose positions and proper motions define the celestial reference frame of Gaia catalogue.</p> <p> <tt>AgnCrossId</tt> lists the sources in Gaia (E)DR3 cross-matched to sources in a number of external AGN catalogues. The first column is the sources identifier in the external catalogue specified in the third column, the second column is the source identifier in Gaia (E)DR3.</p> <p>The selection of sources and the quality of the Gaia-CRF3 are discussed in</p> <p>EDR3-DPACP-133.</p>', 3, 1614173, NULL, '(solo en el Archivo Gaia; bulk en https://cdn.gea.esac.esa.int/?prefix=Gaia/gedr3/)');
INSERT INTO meta_catalogo_tablas VALUES ('Reference_frame', 'Marco de referencia', 'gaiadr3', 'frame_rotator_source', 'TAP Gaia (ADQL)', 'Sources used to compute the Gaia reference frame. The AGIS frame rotator algorithm has two different parts: the reference frame orientation; and the reference frame spin. The reference frame orientation is fixed using the International Earth Rotation and Reference System Service (=IERS) position of a subset of IERS sources defining the third realization of the International Coordinate Reference Frame (Charlot et al., 2020, submitted to A&A), http://hpiers.obspm.fr/icrs-pc/newwww/icrf/index.php. The reference frame spin is defined using the Gaia proper motion of a list of QSOs. The reference frame algorithms have an outliers scheme. Hence for each aspect we provide the considered sources and the used sources actually used, and the number of used sources might be lower than the number of considered sources.', 5, 429249, NULL, '(solo en el Archivo Gaia; bulk en https://cdn.gea.esac.esa.int/?prefix=Gaia/gedr3/)');
INSERT INTO meta_catalogo_tablas VALUES ('Reference_frame', 'Marco de referencia', 'gaiadr3', 'gaia_crf3_xm', 'TAP Gaia (ADQL)', 'This table contains the full cross-match information for the Gaia-CRF3 sources. The Gaia-CRF3 sources were selected from the cross-matches with 17 external QSO catalogues as detailed below (three of which are parts of ICRF3 described in the first paper). For each Gaia-CRF3 source the information in which external catalogue this source was found and which name(s) this source has in those external catalogues is provided. The table allows the user to get all sources from an external catalogue that are in Gaia-CRF3. The external catalogues from which the Gaia-CRF3 sources were compiled are: \begin{itemize} \item The third realization of the International Celestial Reference Frame by very long baseline interferometry \citep{2020A&A...644A.159C} \item A New Version of the OCARS Catalogue of Optical Characteristics of Astrometric Radio Sources \citep{2018ApJS..239...20M} (the catalogue downloaded from \url{http://www.gaoran.ru/english/as/ac_vlbi/#OCARS} on 17 June 2020) \item Identification of 1.4 Million Active Galactic Nuclei in the Mid-Infrared using WISE Data \citep{2015ApJS..221...12S} \item The WISE AGN Catalogue \citep{2018ApJS..234...23A} \item The Million Quasars (Milliquas) Catalogue, v6.4 \citep{2019arXiv191205614F} with the v6.5 (2020) update \item The Sloan Digital Sky Survey Quasar Catalogue: Fourteenth data release \citep{2018A&A...613A..51P} \item LQAC-5: The fifth release of the Large Quasar Astrometric Catalogue. A compilation of 592 809 objects with 398 697 Gaia counterparts \citep{2019A&A...624A.145S} \item The Large Sky Area Multi-object Fiber Spectroscopic Telescope (LAMOST) Quasar Survey: The Fourth and Fifth Data Releases \citep{2019ApJS..240....6Y} -- see also \url{https://nadc.china-vo.org/data/article/20190107155838} \item The large quasar reference frame (LQRF). An optical representation of the ICRS \citep{2009A&A...505..385A} \item The 2dF QSO Redshift Survey - XII. The spectroscopic catalogue and luminosity function \citep{2004MNRAS.349.1397C} \item The 5th edition of the Roma-BZCAT \citep{2015Ap&SS.357...75M} \item 2WHSP: A multi-frequency selected catalogue of high energy and very high energy {\ensuremath{\gamma}}-ray blazars and blazar candidates \citep{2017A&A...598A..17C} \item ALMA photometry of extragalactic radio sources \citep{2019MNRAS.485.1188B} \item Catalogues of active galactic nuclei from Gaia and unWISE data \citep{2019MNRAS.489.4741S} \item Quasar and galaxy classification in Gaia Data Release 2 \citep{2019MNRAS.490.5615B} \end{itemize}', 37, 1614173, 0.063, 'https://cdn.gea.esac.esa.int/?prefix=Gaia/gdr3/Reference_frame/gaia_crf3_xm/');
INSERT INTO meta_catalogo_tablas VALUES ('Science_alerts', 'Alertas científicas', 'gaiadr3', 'alerts_mixedin_sourceids', 'TAP Gaia (ADQL)', 'Some photometric science alerts mix transits from their primary source and other sources in the catalogue. This is done when those sources are believed to be associated with a single, astrophysical source. This table lists the identifier for these mixed-in sources, linking them to the primary sourceIds listed in table \texttt{ScienceAlerts}.', 3, 94, 0.0, 'https://cdn.gea.esac.esa.int/?prefix=Gaia/gdr3/Science_alerts/alerts_mixedin_sourceids/');
INSERT INTO meta_catalogo_tablas VALUES ('Science_alerts', 'Alertas científicas', 'gaiadr3', 'science_alerts', 'TAP Gaia (ADQL)', 'Table containing all Gaia Photometric Science Alerts triggered in the period 25-07-2014 to 28-05-2017, i.e.~the time span covered by DR3. A Gaia Photometric Science Alert is known to the community by its name Gaiannxyz where nn is the year number and xyz is an incrementing, alphabetic sequence starting at aaa. Science alerts have their details published on the WWW. Given the name of an alert, the URL for the published details can be derived, e.g. \url{https://gsaweb.ast.cam.ac.uk/alerts/alert/Gaia18ahj} for alert Gaia18ahj. The {\tt sourceId} associated to the alert may have other alternative matches in Gaia DR3. These other identifiers are listed in table \texttt{AlertsMixedinSourceids}.', 4, 2612, 0.0, 'https://cdn.gea.esac.esa.int/?prefix=Gaia/gdr3/Science_alerts/science_alert/');
INSERT INTO meta_catalogo_tablas VALUES ('Solar_system', 'Sistema solar', 'gaiadr3', 'sso_observation', 'TAP Gaia (ADQL)', 'Solar System object observations. Each table line contained data obtained during the transit of the source on a single CCD, during a single transit. The corresponding epoch is provided. Data not varying within the transit are repeated identically for all single observations of that transit.', 35, 23336467, 4.639, 'https://cdn.gea.esac.esa.int/?prefix=Gaia/gdr3/Solar_system/sso_observation/');
INSERT INTO meta_catalogo_tablas VALUES ('Solar_system', 'Sistema solar', 'gaiadr3', 'sso_reflectance_spectrum', 'TAP Gaia (ADQL)', 'This table contains the mean BP/RP reflectance spectra of asteroids computed as the ratio between the asteroid flux and an averaged solar analogue flux. In each row, the reflectance spectrum of a given asteroid is given at a given wavelength. Entries for all asteroids are concatenated into a single table.', 10, 968288, 0.013, 'https://cdn.gea.esac.esa.int/?prefix=Gaia/gdr3/Solar_system/sso_reflectance_spectrum/');
INSERT INTO meta_catalogo_tablas VALUES ('Solar_system', 'Sistema solar', 'gaiadr3', 'sso_source', 'TAP Gaia (ADQL)', 'This table contains data related to Solar System objects observed by Gaia. The quantities in the table are derived from data reduction and are associated to single objects.', 6, 158152, 0.002, 'https://cdn.gea.esac.esa.int/?prefix=Gaia/gdr3/Solar_system/sso_source/');
INSERT INTO meta_catalogo_tablas VALUES ('Spectroscopy', 'Espectroscopía', 'gaiadr3', 'rvs_mean_spectrum', 'DataLink (RVS)', 'This is the RVS mean sampled spectrum table. The spectra are in the rest frame, they are normalised and their wavelength grid ranges from 846 to 870 nm in steps of 0.01 nm (2401 elements). See~~\secref{sssec:cu6spe_meanspe} for a description on how the mean spectra are obtained, and \citet{DR3-DPACP-154} for a description of the spectra validation. Note this table is not available through the main archive TAP interface, but via the Massive Data service, indexed by the VO Datalink protocol, described in Chapter~\ref{chap:archive}. For example this can be actioned in the archive user interface by querying the main source catalogue {\tt GaiaSource} and selecting {\tt hasRvs}~{\tt = ''t''}. The following columns are available in table format only if the `RAW'' option is selected in the Datalink pop-up window. If the `INDIVIDUAL'' or `COMBINED'' options are chosen, all columns other than {\tt flux} and {\tt fluxError} are provided in the header of the xml file, while wavelength, {\tt flux} and {\tt fluxError} columns are provided in table format.', 9, NULL, 20.423, 'https://cdn.gea.esac.esa.int/?prefix=Gaia/gdr3/Spectroscopy/rvs_mean_spectrum/');
INSERT INTO meta_catalogo_tablas VALUES ('Spectroscopy', 'Espectroscopía', 'gaiadr3', 'xp_continuous_mean_spectrum', 'DataLink (XP_CONTINUOUS)', 'Table hosting the mean BP and RP spectra based on the continuous representation in basis functions (see~\secref{cu5pho_ssec:meanSpecGen}). Note this table is not available through the main archive TAP interface. Data are delivered via the Massive Data service indexed by the VO Datalink protocol and described in Chapter~\ref{chap:archive}. For example this can be actioned in the archive user interface by querying the main source catalogue {\tt GaiaSource} and selecting {\tt hasXpContinuous}~{\tt = ''t''}.', 26, NULL, 3609.79, 'https://cdn.gea.esac.esa.int/?prefix=Gaia/gdr3/Spectroscopy/xp_continuous_mean_spectrum/');
INSERT INTO meta_catalogo_tablas VALUES ('Spectroscopy', 'Espectroscopía', 'gaiadr3', 'xp_sampled_mean_spectrum', 'DataLink (XP_SAMPLED)', 'This is the BP/RP externally calibrated sampled mean spectrum. All mean spectra are sampled to the same set of absolute wavelength positions, viz.~343 values from 336~to 1020~nm with a step of 2~nm. Note this table is not available through the main archive TAP interface. Data are delivered via the Massive Data service indexed by the VO Datalink protocol and described in Chapter~\ref{chap:archive}. For example this can be actioned in the archive user interface by querying the main source catalogue {\tt GaiaSource} and selecting {\tt hasXpSampled}~{\tt = ''t''}.', 6, NULL, 114.427, 'https://cdn.gea.esac.esa.int/?prefix=Gaia/gdr3/Spectroscopy/xp_sampled_mean_spectrum/');
INSERT INTO meta_catalogo_tablas VALUES ('Spectroscopy', 'Espectroscopía', 'gaiadr3', 'xp_summary', 'TAP Gaia (ADQL)', 'This tables contains auxiliary information about the mean BP/RP spectrum of a given source. It should be used in order to refine queries on spectra and build dedicated samples before interrogating the DataLink protocol to download the results of those queries.', 20, 219197643, 9.698, 'https://cdn.gea.esac.esa.int/?prefix=Gaia/gdr3/Spectroscopy/xp_summary/');
INSERT INTO meta_catalogo_tablas VALUES ('Variability', 'Variabilidad', 'gaiadr3', 'vari_agn', 'TAP Gaia (ADQL)', 'This table provides information on AGN properties.', 7, 872228, 0.031, 'https://cdn.gea.esac.esa.int/?prefix=Gaia/gdr3/Variability/vari_agn/');
INSERT INTO meta_catalogo_tablas VALUES ('Variability', 'Variabilidad', 'gaiadr3', 'vari_cepheid', 'TAP Gaia (ADQL)', 'This table describes the Cepheid stars.', 81, 15021, 0.012, 'https://cdn.gea.esac.esa.int/?prefix=Gaia/gdr3/Variability/vari_cepheid/');
INSERT INTO meta_catalogo_tablas VALUES ('Variability', 'Variabilidad', 'gaiadr3', 'vari_classifier_class_definition', 'TAP Gaia (ADQL)', 'Table with detailed descriptions of published classes for each classifier described in {\tt VariClassifierDefinition} and used in table {\tt VariClassifierResult}. In DR3, this table contains the details of a classifier with {\tt classifierName}=`nTransits:5+.', 4, 24, 0.0, 'https://cdn.gea.esac.esa.int/?prefix=Gaia/gdr3/Variability/vari_classifier_class_definition/');
INSERT INTO meta_catalogo_tablas VALUES ('Variability', 'Variabilidad', 'gaiadr3', 'vari_classifier_definition', 'TAP Gaia (ADQL)', 'Table with detailed descriptions of all classifiers used in table {\tt VariClassifierResult}. Details of the published classes for each classifier can be found in {\tt VariClassifierClassDefinition}. In DR3, this table contains the details of a classifier with {\tt classifierName}=`nTransits:5+.', 3, 1, 0.0, 'https://cdn.gea.esac.esa.int/?prefix=Gaia/gdr3/Variability/vari_classifier_definition/');
INSERT INTO meta_catalogo_tablas VALUES ('Variability', 'Variabilidad', 'gaiadr3', 'vari_classifier_result', 'TAP Gaia (ADQL)', 'Table with variability classification results of all classifiers, which are identified by the {\tt classifierName} column. In DR3, multiple classifiers (depending on class) are combined into a single classifier with {\tt classifierName}=`nTransits:5+, which is described in {\tt VariClassifierDefinition} and identifies the classes defined in {\tt VariClassifierClassDefinition}.', 5, 9976881, 0.151, 'https://cdn.gea.esac.esa.int/?prefix=Gaia/gdr3/Variability/vari_classifier_result/');
INSERT INTO meta_catalogo_tablas VALUES ('Variability', 'Variabilidad', 'gaiadr3', 'vari_compact_companion', 'TAP Gaia (ADQL)', 'This table describes the compact companion candidates.', 26, 6306, 0.004, 'https://cdn.gea.esac.esa.int/?prefix=Gaia/gdr3/Variability/vari_compact_companion/');
INSERT INTO meta_catalogo_tablas VALUES ('Variability', 'Variabilidad', 'gaiadr3', 'vari_eclipsing_binary', 'TAP Gaia (ADQL)', 'This table describes the properties of the eclipsing binaries resulting from the variability analysis.', 39, 2184477, 0.345, 'https://cdn.gea.esac.esa.int/?prefix=Gaia/gdr3/Variability/vari_eclipsing_binary/');
INSERT INTO meta_catalogo_tablas VALUES ('Variability', 'Variabilidad', 'gaiadr3', 'vari_epoch_radial_velocity', 'TAP Gaia (ADQL)', 'This table contains the epoch radial velocity data points for a sub-set of variable stars. Each entry is a radial velocity in the solar barycentric reference frame for a given object and observation time.', 7, 43298, 0.003, 'https://cdn.gea.esac.esa.int/?prefix=Gaia/gdr3/Variability/vari_epoch_radial_velocity/');
INSERT INTO meta_catalogo_tablas VALUES ('Variability', 'Variabilidad', 'gaiadr3', 'vari_long_period_variable', 'TAP Gaia (ADQL)', 'This table describes the Long Period Variable stars. Some entries can be NaN when absent.', 7, 1720588, 0.032, 'https://cdn.gea.esac.esa.int/?prefix=Gaia/gdr3/Variability/vari_long_period_variable/');
