INSERT INTO meta_catalogo_tablas VALUES ('Variability', 'Variabilidad', 'gaiadr3', 'vari_rad_vel_statistics', 'TAP Gaia (ADQL)', 'Statistical parameters of radial velocity time series, using only transits not rejected, see {\tt rejectedByVariability} column in {\tt VariEpochRadialVelocity}. Note that NaN will be reported when the parameter value is missing or cannot be calculated.', 16, 1898, 0.001, 'https://cdn.gea.esac.esa.int/?prefix=Gaia/gdr3/Variability/vari_rad_vel_statistics/');
