INSERT INTO meta_catalogo_tablas VALUES ('Variability', 'Variabilidad', 'gaiadr3', 'vari_summary', 'TAP Gaia (ADQL)', 'Summary table that provides the information on where a {\tt sourceId} can be found in the different {\tt Variability} tables and statistical parameters of time series, using only transits not rejected. Note that NULL is reported when the statistical parameter value is missing or cannot be calculated.', 68, 11754237, 3.095, 'https://cdn.gea.esac.esa.int/?prefix=Gaia/gdr3/Variability/vari_summary/');
INSERT INTO meta_catalogo_tablas VALUES ('Simulation', 'Simulación', 'gaiadr3', 'gaia_source_simulation', 'TAP Gaia (ADQL)', 'Table of sources realised according to the Gaia Object Generator (GOG) simulation. Observed attributes are given with simulated observational uncertainties. This table contains the output of GOG. The values are obtained after adding the corresponding uncertainty (based on the error models) to the true values in table GaiaUniverseModel. Both the values and the uncertainties are provided.', 38, 1644237695, NULL, '(solo en el Archivo Gaia; bulk en https://cdn.gea.esac.esa.int/?prefix=Gaia/gedr3/)');
INSERT INTO meta_catalogo_tablas VALUES ('Simulation', 'Simulación', 'gaiadr3', 'gaia_universe_model', 'TAP Gaia (ADQL)', 'Table of simulated galactic stars according to the Gaia Universal Model Simulation (GUMS). True values of the intrinsic simulated quantities (astrometry, photometry and physical parameters) for the sources generated by GOG using the Universe Model are given. No errors are added.', 43, 4378670080, NULL, '(solo en el Archivo Gaia; bulk en https://cdn.gea.esac.esa.int/?prefix=Gaia/gedr3/)');
INSERT INTO meta_catalogo_tablas VALUES ('Auxiliary', 'Auxiliar', 'gaiadr3', 'commanded_scan_law', 'TAP Gaia (ADQL)', 'This table provides a representation of the Gaia scanning law over the 34 month time period covered by the Gaia Data Release 3 (from 2014-07-25 10:31:26 to 2017-05-28 08:46:29), including the Ecliptic Pole Scanning at the begin of the mission. Note that this is the commanded attitude of the spacecraft, the actual attitude could deviate from it by up to about 30 arcsec. Also, it does not contain any of the data interruptions that occurred during the real mission, of which the main ones are listed in Chapter [chap:cu0int], Section [cu0int_sec:release_framework]. The scanning law has been sampled at a 10 second interval, in which the satellite rotates about 10 arcminutes (the target spin rate is actually 59.9641857803 arcsec/sec). Note that this is several times shorter than a typical field-of-view transit and the scan position angle will be practically constant during this interval. Notes: - The times in columns 1, 2 and 3 are in Julian days in TCB with time origin 2010-01-01T00:00 (JD 2455197.5), following the time coordinate convention used in the Gaia archive. TCB stands for Barycentric Coordinate Time and is the time standard used in Gaia processing, equivalent to the proper time experienced by a clock at rest in a coordinate frame co-moving with the barycentre of the Solar system but outside its gravity well, therefore not influenced by the gravitational time dilation caused by the Sun and the rest of the solar system. - Column 1 is the reference time for the spacecraft attitude, while columns 2 and 3 give the times with the (relativistic) corrections applied for the light-travel time to the solar system barycentre, corresponding to an infinitely distant source at the RA, DEC at the centres of FOV 1 and 2, respectively. - FOV1 and FOV2 correspond to the preceding (PFOV) and following (FFOV) fields-of-view, respectively. - The centres of the field of views are separated by the basic angle of 106.5 deg, see Fig. 2 of . Their origin in the focal plane is illustrated in Fig. 3 of the same paper: both originate in the astrometric field (AF) 7, with FOV1 in row 3 and FOV2 in row 5. - The scan angle, theta, is the position angle of the direction in which the FOV is moving (also called ‘along-scan’ direction), and is defined in the usual astronomical sense: theta = 0 when the FoV is moving towards local North, and theta = 90 degrees towards local East. - All values have been formatted to the default double numerical precision and so this precision should not be interpreted as the accuracy of the data.', 13, 8967691, NULL, '(solo en el Archivo Gaia; bulk en https://cdn.gea.esac.esa.int/?prefix=Gaia/gedr3/)');
