INSERT INTO meta_catalogo_tablas VALUES ('SPHEREx_local', 'SPHEREx: resultados de API guardados localmente', 'spherex', 'imagenes', 'SIA2 IRSA (spherex_api.py imagenes)', 'Imágenes espectrales SPHEREx encontradas con SIA2 (una fila por imagen/detector). No guarda los píxeles, solo metadatos y las URLs para descargarlas o recortarlas.', 22, NULL, NULL, '(local: se llena con scripts/spherex_api.py)');
