INSERT INTO meta_catalogo_tablas VALUES ('Proyecto', 'Integración Gaia DR3 + SPHEREx', 'proyecto', 'espectro_spherex', 'Calculado (spherex_api.py espectro)', 'Espectro infrarrojo SPHEREx (0.75-5 µm) de fuentes Gaia: una fila por fuente y por imagen donde aparece. Fotometría de apertura sobre los píxeles leídos directamente de S3. Enlaza con gaiadr3.* por source_id.', 19, NULL, NULL, '(local: se llena con scripts/spherex_api.py)');
