-- Catálogo de tablas y diccionario de columnas Gaia DR3 + SPHEREx (consultables con SQL).
DROP TABLE IF EXISTS meta_catalogo_tablas;
CREATE TABLE meta_catalogo_tablas (categoria text, categoria_es text, esquema text, tabla text, acceso text, descripcion text, columnas integer, filas_origen bigint, gb_comprimido_cdn numeric, url text, PRIMARY KEY (esquema, tabla));
BEGIN;
COMMIT;
DROP TABLE IF EXISTS meta_diccionario_columnas;
CREATE TABLE meta_diccionario_columnas (esquema text, tabla text, posicion integer, columna text, tipo_origen text, tipo_postgres text, tipo_sqlite text, unidad text, ucd text, indexada_en_archivo boolean, descripcion text, PRIMARY KEY (esquema, tabla, columna));
BEGIN;
COMMIT;
